const key = (env.get("OPENWEATHER_API_KEY") || "").trim();
if (!key) {
    return [null, { payload: "Meteorología: falta OPENWEATHER_API_KEY" }];
}
const city = (env.get("OPENWEATHER_CITY") || "Vigo,ES").trim() || "Vigo,ES";
const url = "https://api.openweathermap.org/data/2.5/weather"
    + "?q=" + encodeURIComponent(city)
    + "&units=metric&lang=es&appid=" + encodeURIComponent(key);
return [{ url, requestTimeout: 10000 }, null];

const data = msg.payload;
if (msg.statusCode !== 200) {
    const hint = {
        401: "verifica la activación de la clave",
        404: "revisa OPENWEATHER_CITY",
        429: "límite de consultas alcanzado"
    }[msg.statusCode];
    return { payload: "Meteorología no disponible (HTTP " + msg.statusCode
        + (hint ? ": " + hint : "") + ")" };
}
if (!data || !Number.isFinite(data.main?.temp)
    || !Number.isFinite(data.main?.humidity) || !Number.isFinite(data.dt)
    || !data.name || !data.weather?.[0]?.description) {
    return { payload: "Meteorología: respuesta incompleta" };
}
const weather = {
    city: data.name,
    country: data.sys?.country,
    temperatureC: data.main.temp,
    humidityPct: data.main.humidity,
    description: data.weather[0].description,
    observedAt: new Date(data.dt * 1000).toISOString(),
    conditionId: data.weather[0].id,
    rain: (data.weather[0].id >= 200 && data.weather[0].id < 700) ||
        !!(data.rain && Object.values(data.rain).some(x => typeof x === 'number' && x > 0)) ||
        !!(data.snow && Object.values(data.snow).some(x => typeof x === 'number' && x > 0)),
    storm: data.weather[0].id >= 200 && data.weather[0].id < 300
};
const time = new Intl.DateTimeFormat("es-ES", {
    timeZone: "Europe/Madrid", hour: "2-digit", minute: "2-digit",
    day: "2-digit", month: "2-digit"
}).format(new Date(weather.observedAt));
return {
    weather,
    payload: weather.city + " · " + weather.temperatureC.toFixed(1) + " °C · "
        + weather.humidityPct + " % HR · " + weather.description + " · " + time
};

if (!msg.weather) return null;
return {
    topic: 'bunkeros/weather',
    payload: {
        ciudad: msg.weather.city,
        temperatura: msg.weather.temperatureC,
        descripcion: msg.weather.description,
        lluvia: typeof msg.weather.rain === 'boolean' ? msg.weather.rain : null,
        tormenta: typeof msg.weather.storm === 'boolean' ? msg.weather.storm : null,
        observedAt: msg.weather.observedAt
    }
};

// BunkerOS · Cloud P1. Este bloque NO controla actuadores físicos.
// Entradas reales: msg.topic=bunkeros/live y objeto {temperatura,humedad,nivelAgua,puertaAbierta,fugaAgua}
// Clima: msg.topic=bunkeros/weather y objeto {ciudad,temperatura,descripcion,lluvia}
// Simulación: msg.topic=bunkeros/demo; tick, {action:toggle,key}, {action:all}, {action:reset}
const keys=['calor','humedad','agua','puerta','fuga'];
const makeFlags=()=>({calor:false,humedad:false,agua:false,puerta:false,fuga:false});
const makeEmpty=()=>({temperatura:null,humedad:null,gasPpm:null,nivelAgua:null,puertaAbierta:null,fugaAgua:null,fanEstado:null,valvulaEstado:null});
let s=context.get('bunkerV3')||{mode:'demo',data:makeEmpty(),demoFlags:makeFlags(),history:[],events:[],flags:[],meteo:null,lastUpdate:null};
if(!s.demoFlags) s.demoFlags=makeFlags();
const p=msg.payload, now=Date.now();
const event=(text,level='info')=>{s.events.unshift({ts:now,text,level});s.events=s.events.slice(0,20);};
const finite=(v,min,max)=>typeof v==='number'&&Number.isFinite(v)?Math.max(min,Math.min(max,v)):null;
function apply(q){
 for(const [k,min,max] of [['temperatura',-30,80],['humedad',0,100],['gasPpm',0,100000],['nivelAgua',0,100]]){
  if(Object.prototype.hasOwnProperty.call(q,k))s.data[k]=finite(q[k],min,max);
 }
 for(const k of ['puertaAbierta','fugaAgua']){
  if(Object.prototype.hasOwnProperty.call(q,k))s.data[k]=typeof q[k]==='boolean'?q[k]:null;
 }
 for(const [k,vals] of [['fanEstado',['ON','OFF']],['valvulaEstado',['OPEN','CLOSED']]]){
  if(Object.prototype.hasOwnProperty.call(q,k))s.data[k]=vals.includes(q[k])?q[k]:null;
 }
}
let measurement=false;
if(msg.topic==='bunkeros/weather'){
 if(!p||typeof p!=='object'||Array.isArray(p))return null;
 s.meteo={ciudad:String(p.ciudad||'Localidad'),temperatura:finite(p.temperatura,-80,80),descripcion:String(p.descripcion||'Sin descripción'),lluvia:typeof p.lluvia==='boolean'?p.lluvia:null,tormenta:typeof p.tormenta==='boolean'?p.tormenta:null,observedAt:Date.parse(p.observedAt)||null,ts:now};
}else if(msg.topic==='bunkeros/actuator-status'){
 if(!p||typeof p!=='object'||Array.isArray(p))return null;
 // Estado confirmado por el motor virtual: nunca suponer ejecución desde el botón.
 apply({fanEstado:p.fan_state,valvulaEstado:p.valve_state});
 if(typeof p.command_result==='string'&&p.command_result){
  const ts=Date.parse(p.timestamp);
  // Evitar mostrar respuestas retenidas antiguas después de reconectar MQTT.
  if(Number.isFinite(ts)&&Math.abs(now-ts)<90000){
   let text,level='info',type='success';
   if(p.command_result==='REJECTED_INTERLOCK'||p.valve_error==='interlock_active'){
    text=s.data.fugaAgua===true?'Comando rechazado: bloqueo de seguridad activo. Se ha detectado una fuga de agua.':'Comando rechazado: interbloqueo de seguridad activo; no es seguro abrir la válvula.';level='warning';type='error';
   }else if(p.command_result==='REJECTED_SAFETY_OVERRIDE'||p.fan_error==='safety_override'){
    text='Comando rechazado: el extractor debe permanecer encendido por seguridad.';level='warning';type='error';
   }else if(p.command_result==='ACCEPTED'){
    text='Comando aceptado por el controlador virtual. Estado confirmado por MQTT.';
   }else{
    text='Resultado del comando: '+String(p.command_result);
   }
   s.lastCommand={type,text,ts,result:p.command_result};
   event(text,level);
  }
 }
}else if(msg.topic==='bunkeros/demo'){
 if(p==='tick'&&s.mode==='live')return null;
 if(s.mode==='live')return null; // se evita mezclar datos reales y pruebas
 if(p!=='tick'){
  if(!p||typeof p!=='object'||Array.isArray(p))return null;
  if(p.action==='reset'){
   s.demoFlags=makeFlags();event('Simulación restablecida');
  }else if(p.action==='all'){
   s.demoFlags=Object.fromEntries(keys.map(k=>[k,true]));event('Prueba combinada: todas las condiciones activadas','warning');
  }else if(p.action==='toggle'&&keys.includes(p.key)){
   s.demoFlags[p.key]=!s.demoFlags[p.key];event((s.demoFlags[p.key]?'Activada':'Desactivada')+' condición de prueba: '+p.key);
  }else return null;
 }
 const f=s.demoFlags;
 const jitter=(x,delta)=>Math.round((x+(Math.random()-.5)*delta)*10)/10;
 apply({temperatura:jitter(f.calor?34:23.5,.8),humedad:jitter(f.humedad?74:53,1.6),nivelAgua:jitter(f.agua?14:78,1.4),puertaAbierta:!!f.puerta,fugaAgua:!!f.fuga});
 measurement=true;
}else if(msg.topic==='bunkeros/live'){
 let q=p;
 if(typeof q==='string'){try{q=JSON.parse(q);}catch(e){node.warn('Telemetría JSON no válida');return null;}}
 if(!q||typeof q!=='object'||Array.isArray(q)||!['temperatura','humedad','gasPpm','nivelAgua','puertaAbierta','fugaAgua','fanEstado','valvulaEstado'].some(k=>Object.prototype.hasOwnProperty.call(q,k)))return null;
 if(s.mode!=='live'){
  s.mode='live';s.history=[];s.events=[];s.flags=[];s.data=makeEmpty();event('Recepción de telemetría MQTT externa');
 }
 apply(q);measurement=true;
}else return null;
const d=s.data;
if(measurement){
 s.lastUpdate=now;s.history.push({ts:now,temperatura:d.temperatura,nivelAgua:d.nivelAgua});s.history=s.history.slice(-50);
}
const rules=[
 {id:'calor',active:d.temperatura!==null&&d.temperatura>=30,text:'Temperatura elevada',level:'warning'},
 {id:'humedad',active:d.humedad!==null&&d.humedad>=70,text:'Humedad elevada',level:'warning'},
 {id:'agua',active:d.nivelAgua!==null&&d.nivelAgua<60,text:'Reserva de agua baja (< 60 %)',level:'warning'},
 {id:'puerta',active:d.puertaAbierta===true,text:'Puerta abierta',level:'warning'},
 {id:'fuga',active:d.fugaAgua===true,text:'Fuga de agua detectada',level:'critical'},
 {id:'meteorologia',active:d.puertaAbierta===true&&s.meteo&&s.meteo.observedAt&&now-s.meteo.observedAt<5400000&&(s.meteo.lluvia===true||s.meteo.tormenta===true),text:'PRIORITARIO: escotilla abierta con lluvia/tormenta actual',level:'warning'}
];
const flags=rules.filter(r=>r.active).map(r=>r.id);
for(const r of rules){
 if(r.active&&!s.flags.includes(r.id))event(r.text,r.level);
 if(!r.active&&s.flags.includes(r.id))event('Alerta desactivada: '+r.text,'info');
}
s.flags=flags;
if(!s.events.length&&measurement)event('Monitorización inicializada');
context.set('bunkerV3',s);
msg.payload={...s,alerts:rules.filter(r=>r.active),complete:['temperatura','humedad','gasPpm','nivelAgua','puertaAbierta','fugaAgua'].every(k=>d[k]!==null&&d[k]!==undefined)};
return msg;

const defaults = {
    calor: false,
    humedad: false,
    reservaBaja: false,
    fuga: false,
    escotillaAbierta: false,
    gas: false
};
let estados = Object.assign({}, defaults, flow.get('escenarios') || {});
const comando = msg.payload;
if (comando === 'reset') {
    estados = { ...defaults };
} else if (Object.prototype.hasOwnProperty.call(defaults, comando)) {
    estados[comando] = !estados[comando];
} else {
    return null;
}
flow.set('escenarios', estados);
msg.payload = estados;
return msg;

// DHT22 + MQ-2 virtuales: gas_ppm es una SIMULACION, no una medida calibrada.
const s = flow.get('escenarios') || {};
msg.topic = 'sensor/dht11';
msg.payload = {
    temperature_c: Number((s.calor ? 34 + Math.random() : 23 + Math.random() * 3).toFixed(1)),
    humidity_pct: Number((s.humedad ? 78 + Math.random() : 50 + Math.random() * 10).toFixed(1)),
    gas_ppm: Number((s.gas ? 420 + Math.random() * 60 : 95 + Math.random() * 55).toFixed(0))
};
return msg;

const s = flow.get("escenarios") || {};

msg.topic = "sensor/reed";
msg.payload = {
    hatch_state: s.escotillaAbierta ? "open" : "closed"
};

return msg;

const s = flow.get('escenarios') || {};
msg.topic = 'sensor/ultrasonico';
msg.payload = {
    // Rango normal por debajo de 80%, para ensayar reapertura automática.
    tank_level_pct: Number((s.reservaBaja ? 12 + Math.random() * 3 : 74 + Math.random() * 5).toFixed(1))
};
return msg;

const s = flow.get("escenarios") || {};

msg.topic = "sensor/fuga";
msg.payload = {
    leak_detected: !!s.fuga
};

return msg;

// Simulación Cloud de la Fase 1; el ESP32 físico tendrá autoridad en Fase 2.
const BASE = "bunker/g5";
let datos = flow.get('sensores') || {};
const estado = flow.get('actuadores_simulados') || {};

switch (msg.topic) {
    case 'sensor/dht11': datos.ambiente = msg.payload; break;
    case 'sensor/ultrasonico': datos.nivel = msg.payload.tank_level_pct; break;
    case 'sensor/fuga': datos.fuga = msg.payload.leak_detected; break;
    case 'sensor/reed': datos.acceso = msg.payload.hatch_state; break;
    default: return null;
}
flow.set('sensores', datos);
const timestamp = new Date().toISOString();
const salida = [null, null, null];

if (msg.topic === 'sensor/dht11' && datos.ambiente) {
    salida[0] = {
        topic: BASE + '/telemetria/ambiente', qos: 0, retain: false,
        payload: {
            device_id: 'esp32-env-01',
            temperature_c: datos.ambiente.temperature_c,
            humidity_pct: datos.ambiente.humidity_pct,
            gas_ppm: datos.ambiente.gas_ppm,
            // Null hasta que el motor virtual confirme el estado.
            fan_state: estado.fan_state || null,
            timestamp,
            simulated: true
        }
    };
}
if (msg.topic === 'sensor/fuga' &&
    typeof datos.nivel === 'number' && typeof datos.fuga === 'boolean') {
    salida[1] = {
        topic: BASE + '/telemetria/hidrico', qos: 0, retain: false,
        payload: {
            device_id: 'esp32-water-01',
            tank_level_pct: datos.nivel,
            leak_detected: datos.fuga,
            valve_state: estado.valve_state || null,
            timestamp,
            simulated: true
        }
    };
}
if (msg.topic === 'sensor/reed') {
    salida[2] = {
        topic: BASE + '/telemetria/acceso', qos: 1, retain: true,
        payload: {device_id: 'esp32-water-01', hatch_state: datos.acceso, timestamp, simulated: true}
    };
}
return salida;

// Entra únicamente DESPUÉS del interbloqueo del motor virtual de la Fase 1.
const BASE = "bunker/g5";
if (msg.topic !== BASE + '/telemetria/hidrico') return null;
const p = msg.payload;
if (!p || typeof p.leak_detected !== 'boolean') return null;
const fuga = p.leak_detected;
const anterior = context.get('fugaAnterior');
if (anterior === fuga) return null;
if (fuga && p.valve_state !== 'CLOSED') {
    node.warn('Fuga detectada sin confirmación de cierre: no se declara cierre ejecutado');
    return null;
}
context.set('fugaAnterior', fuga);
return {
    topic: BASE + '/alerta/fuga', qos: 1, retain: true,
    payload: {
        device_id: p.device_id || 'esp32-water-01',
        severity: fuga ? 'CRITICAL' : 'INFO',
        event: fuga ? 'WATER_LEAK_TRIGGERED' : 'WATER_LEAK_CLEARED',
        active: fuga,
        ...(fuga ? {action_taken: 'VALVE_CLOSED_IMMEDIATELY'} : {}),
        simulated: true,
        timestamp: new Date().toISOString()
    }
};

const BASE = "bunker/g5";
if (msg.topic !== BASE + '/telemetria/acceso') return null;
const p = msg.payload;
if (!p || !['open', 'closed'].includes(p.hatch_state)) return null;
const armado = flow.get('modoProteccion') === true;
const anterior = context.get('estadoAnterior');
let alarmaActiva = context.get('alarmaActiva') === true;
context.set('estadoAnterior', p.hatch_state);
// Se detecta también si se activa protección con la puerta ya abierta al próximo reporte.
if (armado && p.hatch_state === 'open' && !alarmaActiva) {
    context.set('alarmaActiva', true);
    return {topic: BASE + '/alerta/escotilla', qos: 1, retain: true,
        payload: {device_id: p.device_id || 'esp32-water-01', severity: 'WARNING',
            event: 'UNAUTHORIZED_HATCH_OPEN', active: true, simulated: true,
            timestamp: new Date().toISOString()}};
}
if ((p.hatch_state === 'closed' || !armado) && alarmaActiva) {
    context.set('alarmaActiva', false);
    return {topic: BASE + '/alerta/escotilla', qos: 1, retain: true,
        payload: {device_id: p.device_id || 'esp32-water-01', severity: 'INFO',
            event: 'HATCH_ALERT_CLEARED', active: false, simulated: true,
            timestamp: new Date().toISOString()}};
}
return null;

const BASE = "bunker/g5";
if (msg.topic !== BASE + '/telemetria/hidrico') return null;
let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
if (typeof p === 'string') {try {p = JSON.parse(p);} catch (e) {return null;}}
if (!p || typeof p !== 'object') return null;
const nivel = p.tank_level_pct;
if (typeof nivel !== 'number' || !Number.isFinite(nivel) || nivel < 0 || nivel > 100) return null;
const alerta = nivel < 60;
const anterior = context.get('reservaBajaAnterior');
if (anterior === alerta) return null;
context.set('reservaBajaAnterior', alerta);
return {
    topic: BASE + '/alerta/hidrico', qos: 1, retain: true,
    payload: {device_id: p.device_id || 'esp32-water-01',
        severity: alerta ? 'WARNING' : 'INFO',
        event: alerta ? 'LOW_WATER_LEVEL' : 'WATER_LEVEL_RECOVERED',
        tank_level_pct: nivel, threshold_pct: 60, active: alerta,
        simulated: true, timestamp: new Date().toISOString()}
};

if (msg.payload === "ARM") {
    flow.set("modoProteccion", true);
    node.status({
        fill: "green",
        shape: "dot",
        text: "Protección activada"
    });
}

if (msg.payload === "DISARM") {
    flow.set("modoProteccion", false);
    node.status({
        fill: "grey",
        shape: "ring",
        text: "Protección desactivada"
    });
}

return null;

// FASE 1: motor de actuación VIRTUAL. No sustituye al interlock físico del ESP32.
const BASE = "bunker/g5";
let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { node.warn('JSON no válido'); return null; }
}
if (!p || typeof p !== 'object' || Array.isArray(p)) return null;
let s = context.get('controlBunker') || {
    temperatura: null, gas: null, nivel: null, fuga: null,
    fan: 'OFF', valve: 'OPEN', fanMode: 'AUTO', valveMode: 'AUTO',
    fanRequest: null, valveRequest: null
};
const previousFan = s.fan;
const previousValve = s.valve;
let motivoFan = 'AUTO', motivoValve = 'AUTO';
let resultadoComando = null, valveError = null, fanError = null;
let hidroVerificado = null;

if (msg.topic === BASE + '/telemetria/ambiente') {
    if (typeof p.temperature_c !== 'number' || !Number.isFinite(p.temperature_c)) return null;
    s.temperatura = p.temperature_c;
    if (typeof p.gas_ppm === 'number' && Number.isFinite(p.gas_ppm)) s.gas = p.gas_ppm;
} else if (msg.topic === BASE + '/telemetria/hidrico') {
    if (typeof p.tank_level_pct !== 'number' || !Number.isFinite(p.tank_level_pct) ||
        p.tank_level_pct < 0 || p.tank_level_pct > 100 ||
        typeof p.leak_detected !== 'boolean') return null;
    s.nivel = p.tank_level_pct;
    s.fuga = p.leak_detected;
    hidroVerificado = p;
} else if (msg.topic === BASE + '/control/ventilacion') {
    if (p.target !== 'fan' || !['ON','OFF','AUTO'].includes(p.action)) return null;
    // Corte de emergencia didáctico; umbral real del MQ-2 requiere calibración.
    const emergency = (s.temperatura !== null && s.temperatura >= 30) || (s.gas !== null && s.gas >= 350);
    if (p.action === 'OFF' && emergency) {
        resultadoComando = 'REJECTED_SAFETY_OVERRIDE';
        fanError = 'safety_override';
    } else {
        s.fanMode = p.action === 'AUTO' ? 'AUTO' : 'MANUAL';
        s.fanRequest = p.action === 'AUTO' ? null : p.action;
        resultadoComando = 'ACCEPTED';
    }
} else if (msg.topic === BASE + '/control/valvula') {
    if (p.target !== 'valve' || !['OPEN','CLOSE','AUTO'].includes(p.action)) return null;
    if (p.action === 'OPEN' && (s.fuga !== false || s.nivel === null || s.nivel >= 100)) {
        resultadoComando = 'REJECTED_INTERLOCK';
        valveError = 'interlock_active';
    } else {
        s.valveMode = p.action === 'AUTO' ? 'AUTO' : 'MANUAL';
        s.valveRequest = p.action === 'AUTO' ? null : p.action;
        resultadoComando = 'ACCEPTED';
    }
} else return null;

const fanEmergency = (s.temperatura !== null && s.temperatura >= 30) || (s.gas !== null && s.gas >= 350);
if (fanEmergency) {
    s.fan = 'ON'; motivoFan = 'SAFETY_OVERRIDE_SIMULATED';
} else if (s.fanMode === 'MANUAL') {
    s.fan = s.fanRequest; motivoFan = 'MANUAL';
} else if (s.temperatura !== null) {
    if (s.temperatura <= 27 && (s.gas === null || s.gas < 350)) s.fan = 'OFF';
    motivoFan = 'TEMPERATURE_CONTROL';
}

if (s.fuga === true) {
    s.valve = 'CLOSED'; motivoValve = 'LEAK_SAFETY';
} else if (s.fuga === false) {
    if (s.valveMode === 'MANUAL') {
        s.valve = s.valveRequest === 'CLOSE' ? 'CLOSED' : 'OPEN';
        motivoValve = 'MANUAL';
    } else if (s.nivel !== null) {
        if (s.nivel >= 100) {s.valve = 'CLOSED'; motivoValve = 'TANK_FULL';}
        else if (s.nivel < 80) {s.valve = 'OPEN'; motivoValve = 'TANK_LOW';}
    }
} else {
    s.valve = 'CLOSED'; motivoValve = 'LEAK_STATUS_UNKNOWN';
}

const timestamp = new Date().toISOString();
const eventos = [];
function evento(topic, event, reason, activo, extra) {
    // En la Wiki: ON/OPEN = QoS1 retain; OFF/CLOSED = QoS0 no retain.
    // Borramos previamente el retained anterior para no dejar un ON/OPEN obsoleto.
    if (!activo) eventos.push({topic, payload: '', qos: 1, retain: true});
    eventos.push({
        topic, qos: activo ? 1 : 0, retain: !!activo,
        payload: Object.assign({event, reason, timestamp, simulated: true}, extra)
    });
}
if (previousFan !== s.fan) {
    evento(BASE + '/evento/ventilacion', s.fan === 'ON' ? 'FAN_ON' : 'FAN_OFF',
        motivoFan, s.fan === 'ON', {device_id: 'esp32-env-01'});
}
if (previousValve !== s.valve) {
    evento(BASE + '/evento/hidrico', s.valve === 'OPEN' ? 'VALVE_OPENED' : 'VALVE_CLOSED',
        motivoValve, s.valve === 'OPEN', {device_id: 'esp32-water-01', tank_level_pct: s.nivel});
}
context.set('controlBunker', s);
flow.set('actuadores_simulados', {fan_state: s.fan, valve_state: s.valve, timestamp});
const estado = {
    topic: BASE + '/estado/actuadores', qos: 1, retain: true,
    payload: {
        device_id: 'bunkeros-cloud-simulator',
        fan_state: s.fan, valve_state: s.valve,
        fan_mode: s.fanMode, valve_mode: s.valveMode,
        command_result: resultadoComando,
        valve_error: valveError, fan_error: fanError,
        simulated: true, timestamp
    }
};
const hidrico = hidroVerificado ? {
    topic: BASE + '/telemetria/hidrico',
    payload: Object.assign({}, hidroVerificado, {valve_state: s.valve})
} : null;
return [eventos.length ? eventos : null, estado, hidrico];

const BASE = "bunker/g5";
const ordenes = {
    FAN_ON: ['ventilacion', 'fan', 'ON'],
    FAN_OFF: ['ventilacion', 'fan', 'OFF'],
    FAN_AUTO: ['ventilacion', 'fan', 'AUTO'],
    VALVE_OPEN: ['valvula', 'valve', 'OPEN'],
    VALVE_CLOSE: ['valvula', 'valve', 'CLOSE'],
    VALVE_AUTO: ['valvula', 'valve', 'AUTO']
};
const orden = ordenes[msg.payload];
if (!orden) return null;
return {
    topic: BASE + '/control/' + orden[0], qos: 1, retain: false,
    payload: {
        target: orden[1], action: orden[2],
        requested_by: msg.topic === 'bunkeros/manual' ? 'dashboard_admin' : 'node_red_test',
        timestamp: new Date().toISOString()
    }
};

let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) {node.warn('Telemetría JSON inválida'); return null;}
}
if (!p || typeof p !== 'object' || Array.isArray(p)) return null;
const d = {};
const base = "bunker/g5/telemetria/";
const num = (src, dest, min, max) => {
    if (typeof p[src] === 'number' && Number.isFinite(p[src]) && p[src] >= min && p[src] <= max)
        d[dest] = p[src];
};
if (msg.topic === base + 'ambiente') {
    num('temperature_c','temperatura',-30,80);
    num('humidity_pct','humedad',0,100);
    num('gas_ppm','gasPpm',0,100000);
    if (['ON','OFF'].includes(p.fan_state)) d.fanEstado = p.fan_state;
} else if (msg.topic === base + 'hidrico') {
    num('tank_level_pct','nivelAgua',0,100);
    if (typeof p.leak_detected === 'boolean') d.fugaAgua = p.leak_detected;
    if (['OPEN','CLOSED'].includes(p.valve_state)) d.valvulaEstado = p.valve_state;
} else if (msg.topic === base + 'acceso') {
    if (p.hatch_state === 'open') d.puertaAbierta = true;
    else if (p.hatch_state === 'closed') d.puertaAbierta = false;
} else return null;
if (!Object.keys(d).length) return null;
return {topic: 'bunkeros/live', payload: d};

// Estado de actuación CONFIRMADO recibido por MQTT; Fase 1 virtual.
let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (_) { return null; } }
if (!p || typeof p !== 'object' || Array.isArray(p)) return null;
if (!['ON','OFF'].includes(p.fan_state) || !['OPEN','CLOSED'].includes(p.valve_state)) return null;
return {
    topic: 'bunkeros/actuator-status',
    payload: {
        fan_state: p.fan_state,
        valve_state: p.valve_state,
        command_result: typeof p.command_result === 'string' ? p.command_result : null,
        valve_error: typeof p.valve_error === 'string' ? p.valve_error : null,
        fan_error: typeof p.fan_error === 'string' ? p.fan_error : null,
        timestamp: p.timestamp
    }
};
